func astNode(v any) *Node    { n, _ := v.(*Node); return n }
func astInt(v any) int       { i, _ := v.(int); return i }
func astString(v any) string { s, _ := v.(string); return s }
func astBool(v any) bool     { x, _ := v.(bool); return x }
func astPtrInt(v any) *int {
	if i, ok := v.(int); ok {
		return &i
	}
	return nil
}
func astPtrString(v any) *string {
	if s, ok := v.(string); ok {
		return &s
	}
	return nil
}
func astPtrBool(v any) *bool {
	if x, ok := v.(bool); ok {
		return &x
	}
	return nil
}

// astChunk owns unused values and the next allocation size for one type.
// Handed-out values are never reused, even when a parse discards them.
type astChunk[T any] struct {
	free []T
	next int
}

// grow starts small and doubles up to limit. The request is always satisfied.
func (s *astChunk[T]) grow(n, initial, limit int) {
	size := s.next
	if size == 0 {
		size = initial
	}
	for size < n {
		size *= 2
	}
	s.free = make([]T, size)
	s.next = size * 2
	if s.next > limit {
		s.next = limit
	}
}

// astNew returns a new zero value from a chunk that grows from 8 to 256 values.
func astNew[T any](s *astChunk[T]) *T {
	if len(s.free) == 0 {
		s.grow(1, 8, 256)
	}
	v := &s.free[0]
	s.free = s.free[1:]
	return v
}

// astSlice returns n zero values with capacity n, so appending cannot overwrite
// another returned slice. Small-list chunks grow from 64 to 1,024 elements.
func astSlice[T any](s *astChunk[T], n int) []T {
	if n == 0 {
		return []T{} // an empty list, not nil
	}
	if n > 256 {
		return make([]T, n)
	}
	if len(s.free) < n {
		s.grow(n, 64, 1024)
	}
	v := s.free[:n:n]
	s.free = s.free[n:]
	return v
}

// tinit sets up the typed rules (called at the end of init, after the rule tables).
func tinit() {
	trules[6].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tIdent)
		*v = Ident{Span: Span{start, end}, Text: text}
		return v
	}
	trules[7].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tIdent)
		*v = Ident{Span: Span{start, end}, Text: text}
		return v
	}
	trules[106].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tStringLit)
		*v = StringLit{Span: Span{start, end}, Text: text}
		return v
	}
	trules[154].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tIdent)
		*v = Ident{Span: Span{start, end}, Text: text}
		return v
	}
	trules[254].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tIdent)
		*v = Ident{Span: Span{start, end}, Text: text}
		return v
	}
	trules[285].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tIntLit)
		*v = IntLit{Span: Span{start, end}, Text: text}
		return v
	}
	trules[286].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tFloatLit)
		*v = FloatLit{Span: Span{start, end}, Text: text}
		return v
	}
	trules[287].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tImagLit)
		*v = ImagLit{Span: Span{start, end}, Text: text}
		return v
	}
	trules[296].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tCharLit)
		*v = CharLit{Span: Span{start, end}, Text: text}
		return v
	}
	trules[297].term = func(p *tparser, start, end int, text string) tval {
		v := astNew(&p.ext.(*tslabs).tStringLit)
		*v = StringLit{Span: Span{start, end}, Text: text}
		return v
	}
}

// tmk_ArrayType makes a ArrayType in an action (newStruct in the typed runtime).
func tmk_ArrayType(c *tctx, final bool, f0 any, f1 any) any {
	a := c.p.ext.(*tslabs)
	v := astNew(&a.tArrayType)
	v.Len = tAs[Expr](tpub(f0))
	v.Elt = tAs[Expr](tpub(f1))
	if final {
		v.Span = Span{c.start, c.end}
		return v
	}
	first, start, end := true, 0, 0
	spanOf(f0, &first, &start, &end)
	spanOf(f1, &first, &start, &end)
	return c.made(v, first, start, end)
}

// tmk_AssignStmt makes a AssignStmt in an action (newStruct in the typed runtime).
